import json,html,collections
from pathlib import Path
P=Path(__file__).resolve().parent;D=json.loads((P/'results.json').read_text());I=json.loads((P/'inputs.json').read_text())
def rub(n):return f'{n:,.0f}'.replace(',','\u202f')+' ₽'
def num(n):return f'{n:,.0f}'.replace(',','\u202f')
def esc(s):return html.escape(str(s))
def table(head,rows):return '<div class="table"><table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
T=D['thresholds'];be=T['0']['planning_orders'];target=T['500000']['planning_orders'];sb=D['scenarios'][str(be)];st=D['scenarios'][str(target)]
