for month,m in I['months'].items():source.append([{'2026-07':'Июль','2026-08':'Август','2026-09':'Сентябрь'}[month],num(m['orders']),rub(float(m['reported_profit'])),rub(m['enterprise']['net']/m['orders'])])
reserve_labels={'equipment_repair':'Ремонт оборудования','recruiting':'Поиск и найм','staff_expenses':'Форма и прочие расходы на персонал','transport':'Перевозки и транспорт','aggregator_commission':'Нерегулярная комиссия агрегатору','bank_fees':'Прочие банковские комиссии','office_maintenance':'Содержание офиса'}
