line_rows=[[esc(x['title']),rub(x['fixed_monthly']) if x['fixed_monthly'] is not None else 'Дневной расчёт',f"{x['per_order']:.2f} ₽" if x['per_order'] is not None else 'По ступеням',rub(x['amount']),esc(x['basis'])] for x in st['budget_lines']]
assumptions=''.join('<li>'+esc(x)+'</li>' for x in D['assumptions'])
